mapper.select:
SELECT p.id AS id, p.title AS title, p.summary AS summary, p.user_id AS userId, u.username AS username, u.avatar AS userAvatar, p.section_id AS sectionId, s.name AS sectionName, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, p.favorite_count AS favoriteCount, p.is_top AS isTop, p.is_essence AS isEssence, p.create_time AS createTime FROM post p LEFT JOIN user u ON p.user_id = u.id AND u.deleted = 0 LEFT JOIN section s ON p.section_id = s.id AND s.deleted = 0 WHERE p.deleted = 0 AND p.status = 0 AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND p.section_id = #{sectionId}
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
ORDER BY p.create_time DESC
